<?php

declare(strict_types=1);

namespace Silin\MagentoPerfCheck\Tests\Unit\Calibration;

use PHPUnit\Framework\TestCase;

/**
 * docs/calibration.md is generated by bin/calibration/report and records round 1: regenerating it from
 * the graded samples and the manifest must give the committed page, byte for byte.
 */
final class ReportTest extends TestCase
{
    public function testRegeneratedPageMatchesTheCommittedOne(): void
    {
        $root = dirname(__DIR__, 3);
        $process = proc_open(
            [PHP_BINARY, '-d', 'display_errors=stderr', $root . '/bin/calibration/report', '--print'],
            [1 => ['pipe', 'w'], 2 => ['pipe', 'w']],
            $pipes,
        );
        self::assertIsResource($process);
        $output = (string) stream_get_contents($pipes[1]);
        $errors = (string) stream_get_contents($pipes[2]);

        self::assertSame(0, proc_close($process), $errors);
        self::assertSame('', $errors);
        self::assertSame((string) file_get_contents($root . '/docs/calibration.md'), $output);
    }
}
